import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportId = req.getParameter("id");
        String format = req.getParameter("format");
        String dateRange = req.getParameter("range");

        // Basic null check
        if (reportId == null || reportId.isEmpty()) {
            resp.sendError(400, "Missing report id");
            return;
        }

        // Length validation - prevents extremely long payloads
        if (reportId.length() > 200) {
            resp.sendError(400, "Parameter too long");
            return;
        }

        // Log access for audit
        log.info(String.format("Report access: id=%s, format=%s, remote=%s",
            reportId, format, req.getRemoteAddr()));

        Connection conn = null;
        Statement stmt = null;
        ResultSet rs = null;

        try {
            conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
            stmt = conn.createStatement();

            // Build query - developer note: parameterized queries TODO for v2
            String query = "SELECT report_name, created_at, payload FROM reports WHERE id = '" 
                + reportId + "'";

            if (dateRange != null && !dateRange.isEmpty()) {
                query += " AND created_at >= '" + dateRange + "'";
            }

            rs = stmt.executeQuery(query);

            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.print("{");
            if (rs.next()) {
                out.print("\"name\":\"" + rs.getString("report_name") + "\",");
                out.print("\"created\":\"" + rs.getString("created_at") + "\",");
                out.print("\"data\":\"" + rs.getString("payload") + "\"");
            } else {
                out.print("\"error\":\"not found\"");
            }
            out.print("}");
            out.flush();

        } catch (SQLException e) {
            log.warning("DB error: " + e.getMessage());
            resp.sendError(500, "Internal error");
        } finally {
            try { if (rs != null) rs.close(); } catch (Exception e) {}
            try { if (stmt != null) stmt.close(); } catch (Exception e) {}
            try { if (conn != null) conn.close(); } catch (Exception e) {}
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        // POST creates a new report - uses PreparedStatement (safe)
        String name = req.getParameter("name");
        String payload = req.getParameter("payload");

        if (name == null || payload == null) {
            resp.sendError(400, "Missing parameters");
            return;
        }

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             PreparedStatement ps = conn.prepareStatement(
                 "INSERT INTO reports (report_name, payload, created_at) VALUES (?, ?, NOW())")) {
            ps.setString(1, name);
            ps.setString(2, payload);
            ps.executeUpdate();
            resp.setStatus(201);
        } catch (SQLException e) {
            log.warning("Insert error: " + e.getMessage());
            resp.sendError(500, "Internal error");
        }
    }
}
